-- Adds 2 new Module 3 lessons filling a real prompting gap: "Prompt Engineering
-- 101" covered role/task/format/constraints, but never few-shot prompting or
-- chain-of-thought prompting -- two of the most standard, high-leverage
-- techniques in every real prompting guide (Anthropic's, OpenAI's,
-- DeepLearning.AI's dedicated prompting course).
--
-- Anchored to a lesson TITLE via subquery, not a hardcoded order_index, so
-- this is safe regardless of what other renumbering migrations have already
-- run. Placed right after "Prompt Engineering 101," before Embeddings/RAG
-- (a different technical direction). Same negate-then-restore trick as prior
-- renumbering migrations; lesson_progress/lesson_quiz_questions key off
-- lesson_id, never order_index.

UPDATE public.lessons SET order_index = -order_index
WHERE order_index > (SELECT order_index FROM public.lessons WHERE module_number = 3 AND title = 'Prompt Engineering 101');
UPDATE public.lessons SET order_index = -order_index + 2 WHERE order_index < 0;

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    3,
    (SELECT order_index FROM public.lessons WHERE module_number = 3 AND title = 'Prompt Engineering 101') + 1,
    'Few-Shot Prompting: Show, Don''t Just Tell',
    'few-shot-prompting',
    'Why 2-3 real examples inside a prompt often beat any amount of written instructions.',
    10,
    true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"Telling a model “format your answer like this” is guessing. SHOWING it 2-3 real examples inside the prompt is nearly cheating — it works that well.","explanation":"Zero-shot prompting is asking a model to do a task with no examples — just instructions (everything covered in “Prompt Engineering 101”). Few-shot prompting adds 2-3 example input/output pairs directly inside the prompt, before your real question. The model pattern-matches your new input against the exact style, format, and reasoning shown in the examples — often dramatically more consistent than instructions alone, especially for oddly-specific formats that are hard to describe in words. The trade-off: examples use up tokens (context window space) and take effort to write well — so few-shot is worth it specifically when the desired format or style is hard to describe, but easy to demonstrate.","analogy":"Telling someone “write formally” is vague. Handing them 3 real formal letters and saying “write like these” removes almost all the ambiguity — that''s the entire difference between zero-shot and few-shot.","fun_fact":"The “shot” in few-shot comes straight from ML jargon for how many labeled examples a model gets: zero-shot, one-shot, few-shot are all points on the exact same scale.","try_it":"Pick a task where the FORMAT is hard to describe in words but easy to show (a very specific text-message style, or a particular code-comment format). Write 2 example input/output pairs you''d use for a few-shot prompt.","code":"zero_shot_prompt = \"Convert this to a polite customer support reply: ''the product broke''\"\n\nfew_shot_prompt = \"\"\"Convert casual complaints into polite customer support replies.\n\nComplaint: \"this is so slow\"\nReply: \"Thank you for flagging this -- we understand the slow performance is frustrating, and we are looking into it right away.\"\n\nComplaint: \"nothing works\"\nReply: \"We are sorry to hear you are running into issues. Could you tell us a bit more so we can help resolve this quickly?\"\n\nComplaint: \"the product broke\"\nReply:\"\"\"\n\nprint(\"ZERO-SHOT gives the model a task description only\")\nprint(\"FEW-SHOT gives the model 2 real examples of the exact style wanted first\")\nprint(f\"\\nFew-shot prompt length: {len(few_shot_prompt.split())} words\")","visual":{"caption":"A scale, not a binary choice","steps":[{"emoji":"0️⃣","label":"Zero-Shot","caption":"Instructions only, no examples."},{"emoji":"1️⃣","label":"One-Shot","caption":"A single example of the desired style."},{"emoji":"🔢","label":"Few-Shot","caption":"2-3 examples, showing a consistent pattern."},{"emoji":"🎯","label":"Model Pattern-Matches","caption":"New input gets handled in the exact style shown."}]},"practice":{"prompt":"When is few-shot prompting MOST worth the extra tokens it costs?","options":["When the desired format or style is hard to describe in words but easy to demonstrate with examples","It is never worth it under any circumstances","Only when the task involves numbers","Only for the very first prompt you ever write"],"correct_index":0,"feedback":"Examples remove ambiguity that instructions alone often cannot — exactly when a plain description struggles to pin down a specific style."}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'What is the difference between zero-shot and few-shot prompting?', '["Few-shot includes 2-3 example input/output pairs in the prompt; zero-shot uses instructions only","Zero-shot is always more accurate than few-shot","Few-shot means the model gets zero information at all","They are two names for the exact same technique"]', 0, 'Few-shot literally means giving the model a few labeled examples to pattern-match against, instead of relying on instructions alone.'),
  (2, 'Why might few-shot prompting produce more consistent output than a written instruction alone?', '["Examples remove ambiguity that a text description often cannot fully capture","Few-shot prompts always use fewer tokens","The model ignores instructions entirely when examples are present","Few-shot prompting disables the model’s reasoning ability"]', 0, 'Showing the exact desired pattern is often far more precise than describing it in words.'),
  (3, 'What is a real cost of using few-shot prompting?', '["The examples use up tokens (context window space) and take effort to write well","It always makes the model refuse to answer","It is completely free with zero trade-offs","It only works with image models, never text"]', 0, 'Every example added to the prompt consumes part of the limited context window.'),
  (4, 'In the code example, what makes few_shot_prompt different from zero_shot_prompt?', '["It includes 2 full example complaint/reply pairs before the real question","It is written in a different programming language","It contains no text at all","It is exactly the same as zero_shot_prompt"]', 0, 'The two example pairs are what turn a zero-shot request into a few-shot one.'),
  (5, 'Where does the term "few-shot" originate from?', '["ML/statistics jargon describing how many labeled examples a model is given","A reference to photography","It has no real meaning, it is just a marketing term","It refers to how fast the model responds"]', 0, 'Zero-shot, one-shot, and few-shot all describe points on the same "how many examples" scale.'),
  (6, 'A task requires a very specific, unusual text format that is hard to explain in a sentence. What prompting approach fits best?', '["Few-shot prompting, since showing the format directly is easier than describing it","Temperature adjustment, since format has nothing to do with sampling","Zero-shot prompting, since instructions are always sufficient","This cannot be solved with prompting at all"]', 0, 'This is exactly the situation few-shot prompting is built for — demonstrating instead of describing.'),
  (7, 'What do the example pairs in a few-shot prompt actually do for the model?', '["Give it a concrete pattern to match the new input against","Physically retrain the model’s weights","Get deleted before the model ever sees them","Have no effect on the model’s output whatsoever"]', 0, 'The model uses the shown examples as a template for how to handle the new, real input.')
) AS q(order_index, question, options, correct_index, explanation);

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    3,
    (SELECT order_index FROM public.lessons WHERE module_number = 3 AND title = 'Prompt Engineering 101') + 2,
    'Chain-of-Thought: Getting AI to Show Its Work',
    'chain-of-thought-prompting',
    'The simple instruction that measurably improves AI accuracy on hard, multi-step questions.',
    10,
    true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"Ask an AI a tricky multi-step question directly, and it might jump to a wrong answer. Ask it to “think step by step” first, and accuracy on hard questions often jumps.","explanation":"Chain-of-thought (CoT) prompting means explicitly asking the model to reason through a problem step by step BEFORE giving its final answer, instead of jumping straight to a conclusion. Since an LLM generates its response one token at a time, forcing it to “show its work” first means each reasoning step becomes part of the context the NEXT step (and the final answer) is generated from — giving the model a chance to catch its own mistakes along the way, the same way a person doing math on paper is less error-prone than someone doing it purely in their head. This is especially valuable for multi-step math, logic puzzles, and any question where jumping straight to an answer skips real reasoning. The simplest version is startlingly effective: just adding the phrase “Let''s think step by step” to a prompt measurably improves accuracy on many reasoning tasks.","analogy":"It''s the difference between blurting out a guess to a multiplication problem versus actually writing out the long multiplication on paper. The paper doesn''t make you smarter — it makes your OWN mistakes visible to you before you commit to a final answer.","fun_fact":"Chain-of-thought prompting is one of the most influential discoveries in modern prompting research — a simple instruction to “think step by step,” with zero extra training, meaningfully improved model performance on reasoning benchmarks.","try_it":"Take a multi-step question (like a word math problem). Write out what a chain-of-thought answer would look like, step by step, before the final answer.","code":"direct_prompt = \"A store had 23 apples. They sold 8, then received a shipment of 15 more. How many apples now?\"\n\ncot_prompt = \"\"\"A store had 23 apples. They sold 8, then received a shipment of 15 more.\nHow many apples now? Let''s think step by step.\n\"\"\"\n\n# What a chain-of-thought RESPONSE looks like -- reasoning shown before the answer\ncot_response = \"\"\"Step 1: Start with 23 apples.\nStep 2: They sold 8, so 23 - 8 = 15 apples remain.\nStep 3: They received 15 more, so 15 + 15 = 30 apples.\nFinal answer: 30 apples.\"\"\"\n\nprint(\"DIRECT prompt asks for just the final number\")\nprint(\"CHAIN-OF-THOUGHT prompt asks the model to reason first\")\nprint()\nprint(cot_response)","visual":{"caption":"Two paths through the same question","steps":[{"emoji":"❓","label":"Question","caption":"A multi-step problem, math or logic."},{"emoji":"⚡","label":"Direct: Jump to Answer","caption":"Riskier — no visible reasoning to catch a mistake."},{"emoji":"🪜","label":"CoT: Reason Step by Step","caption":"Each step becomes context for the next."},{"emoji":"✅","label":"Final Answer","caption":"Reached after visible, checkable reasoning."}]},"practice":{"prompt":"Why does asking a model to \"think step by step\" often improve accuracy on hard questions?","options":["Each reasoning step becomes context for the next, giving the model a chance to catch mistakes before the final answer","It makes the model respond faster","It has no real effect on accuracy at all","It only works for questions with no numbers involved"],"correct_index":0,"feedback":"Visible, step-by-step reasoning lets each step inform the next — the same reason doing math on paper beats doing it purely in your head."},"code_practice":{"instructions":"Turn this into a chain-of-thought prompt by adding an instruction that asks the model to reason before giving its final answer.","starter":"question = \"If a train travels 60 miles in 2 hours, then 90 miles in 3 hours, what is its average speed for the whole trip?\"\n\n# TODO: turn this into a prompt that asks the model to reason before answering\nprompt = question\n\nprint(prompt)","check_pattern":"(step by step|show your (reasoning|work)|reason (through|first)|think (it )?through)","success_message":"Now the model has to reason before answering -- exactly the nudge that improves accuracy on multi-step problems like this one.","hint":"Try adding: \"Let''s think step by step.\" to the end of the question."}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'What is chain-of-thought prompting?', '["Asking the model to reason through a problem step by step before giving its final answer","Asking the model to answer as fast as possible with no explanation","A technique that only works on image-generation models","Randomly chaining together unrelated prompts"]', 0, 'CoT specifically asks for visible, step-by-step reasoning before the final answer, rather than jumping straight to a conclusion.'),
  (2, 'Why can forcing an LLM to "show its work" first improve its final answer?', '["Each reasoning step becomes context feeding into the next step and the final answer","It has no effect, since the model always reasons internally regardless","It makes the model use less electricity","It prevents the model from using any tools"]', 0, 'Because an LLM generates text sequentially, visible reasoning steps become real context the following steps build on.'),
  (3, 'In the apple-store example, what is the correct final answer?', '["30 apples","15 apples","23 apples","8 apples"]', 0, '23 - 8 = 15, then 15 + 15 = 30.'),
  (4, 'What is the simplest, most well-known chain-of-thought technique?', '["Adding the phrase \"Let''s think step by step\" to a prompt","Increasing the temperature setting to maximum","Removing all instructions from the prompt entirely","Asking the same question 10 times in a row"]', 0, 'This simple addition, with zero extra training, has been shown to measurably improve reasoning-task accuracy.'),
  (5, 'For which type of task is chain-of-thought prompting most valuable?', '["Multi-step math or logic problems where jumping straight to an answer risks skipping real reasoning","Simple factual lookups with a single, obvious answer","Tasks that involve no reasoning of any kind","Formatting a document with specific fonts"]', 0, 'CoT shines specifically where multi-step reasoning matters — simple lookups gain little from it.'),
  (6, 'What is the paper-vs-mental-math analogy in this lesson illustrating?', '["Visible reasoning steps make your own mistakes catchable before committing to a final answer","Writing on paper is always faster than typing","Mental math is always more accurate than written math","This analogy has nothing to do with chain-of-thought prompting"]', 0, 'Just like solving math on paper, visible reasoning steps let mistakes get caught along the way, not just at the very end.'),
  (7, 'A direct prompt (no chain-of-thought) is riskier specifically because:', '["There is no visible reasoning to catch a mistake before the final answer is given","It always takes longer to generate a response","It uses significantly more tokens than a CoT prompt","It is technically impossible for a model to answer directly"]', 0, 'Without visible intermediate reasoning, an error made early has no chance of being caught before the final answer is committed to.')
) AS q(order_index, question, options, correct_index, explanation);
